            var url = site === 'mangak.io' ? 'https://mangak.io/search?q=' + encodeURIComponent(query)
                : 'https://api.mangadex.org/manga?limit=24&includes%5B%5D=cover_art&includes%5B%5D=author&title=' + encodeURIComponent(query);
