        searchId++;
        reset('search');
        current = {text: '', tags: [], queries: queries, byId: false, author: name};
        running = 0;
        setRunning(1);
        $('heading').innerHTML = 'Books by ' + esc(name) + ' <a id="backTop">Top 100</a>';
        $('backTop').onclick = function () { showTop(); };
        startProgress(0);
